package com.agentic.shortener.service;

import com.agentic.shortener.ShortenerExceptions.InvalidRequest;
import com.agentic.shortener.ShortenerFixtures;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** The abuse checks in UrlValidator: credentials, IP-literal hosts and local-only hosts are rejected. */
class UrlValidatorAbuseTest {

    private final UrlValidator validator = new UrlValidator(ShortenerFixtures.properties());

    @ParameterizedTest
    @ValueSource(strings = {"https://user:secret@example.com/login", "http://admin@example.com", "https://a:b@example.com:8443/x"})
    void urlsWithEmbeddedCredentialsAreRejected(String url) {
        assertThatThrownBy(() -> validator.validateTargetUrl(url)).isInstanceOf(InvalidRequest.class).hasMessageContaining("credentials");
    }

    @ParameterizedTest
    @ValueSource(strings = {"http://192.168.1.10/admin", "https://8.8.8.8/", "http://127.0.0.1:8080/x", "http://[::1]/x", "https://[2001:db8::1]/"})
    void ipLiteralHostsAreRejected(String url) {
        assertThatThrownBy(() -> validator.validateTargetUrl(url)).isInstanceOf(InvalidRequest.class).hasMessageContaining("IP address");
    }

    @ParameterizedTest
    @ValueSource(strings = {"http://localhost/x", "https://app.localhost/", "http://printer.local/", "https://db.internal/status"})
    void localOnlyHostsAreRejected(String url) {
        assertThatThrownBy(() -> validator.validateTargetUrl(url)).isInstanceOf(InvalidRequest.class);
    }

    @ParameterizedTest
    @ValueSource(strings = {"https://example.com/a?b=c", "http://sub.example.co.uk/x", "https://localhost.example.com/ok", "https://1password.com/",
            "https://example.com/path@with-at-sign"})
    void ordinaryDomainUrlsAreStillAccepted(String url) {
        assertThat(validator.validateTargetUrl(url)).isEqualTo(url);
    }
}
